uniform float amzp_bypassStrength;
uniform float amzp_blendMode;
uniform float amzp_shadowContrast;
uniform float amzp_highlightContrast;
uniform float amzp_midContrast;
uniform float amzp_blackPoint;
uniform float amzp_whitePoint;
uniform float amzp_shadowDesat;
uniform float amzp_midDesat;
uniform float amzp_highlightDesat;
uniform float amzp_grainEnable;
uniform float amzp_grainStrength;
uniform float amzp_grainSize;
uniform float amzp_grainSpeed;
uniform float amzp_halationEnable;
uniform float amzp_halationStrength;
uniform float amzp_halationThreshold;
layout(color) uniform half4 amzp_halationColor;
uniform float amzp_liftShadows;
uniform float amzp_gainHighlights;
uniform float amzp_gamma;
layout(color) uniform half4 amzp_shadowTint;
uniform float amzp_shadowTintStr;
layout(color) uniform half4 amzp_highlightTint;
uniform float amzp_highlightTintStr;
uniform float amzp_overallStrength;
uniform float amzp_bwPreview;


    const float PI = 3.14159265358979323846;

    float luminance(float3 c){
      return dot(c, float3(0.2126, 0.7152, 0.0722));
    }

    float3 srgbToLinear(float3 c){
      float3 cut = step(float3(0.04045), c);
      return mix(c / 12.92, pow((c + 0.055) / 1.055, float3(2.4)), cut);
    }

    float3 linearToSrgb(float3 c){
      c = max(c, float3(0.0));
      float3 cut = step(float3(0.0031308), c);
      return mix(c * 12.92, 1.055 * pow(c, float3(1.0 / 2.4)) - 0.055, cut);
    }

    float hash11(float n){
      return fract(sin(n) * 43758.5453123);
    }

    float hash21(float2 p){
      return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453123);
    }

    float3 blendOverlay(float3 base, float3 blend){
      float3 low  = 2.0 * base * blend;
      float3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
      return mix(low, high, step(0.5, base));
    }

    float3 blendSoftLight(float3 base, float3 blend){
      float3 low  = 2.0 * base * blend + base * base * (1.0 - 2.0 * blend);
      float3 high = sqrt(base) * (2.0 * blend - 1.0) + 2.0 * base * (1.0 - blend);
      return mix(low, high, step(0.5, blend));
    }

    float3 blendHardLight(float3 base, float3 blend){
      float3 low  = 2.0 * base * blend;
      float3 high = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
      return mix(low, high, step(0.5, blend));
    }

    float toneCurve(float v, float lift, float gain, float gam){
      v = clamp(v, 0.0, 1.0);
      v = v * (gain - lift) + lift;
      v = pow(max(v, 0.0001), 1.0 / max(gam, 0.001));
      return clamp(v, 0.0, 1.0);
    }

    float filmContrast(float lum, float shadowC, float highlightC, float midC, float bPoint, float wPoint){
      lum = (lum - bPoint) / max(wPoint - bPoint, 0.0001);
      lum = clamp(lum, 0.0, 1.0);
      float shadowMask    = smoothstep(0.4, 0.0, lum);
      float highlightMask = smoothstep(0.6, 1.0, lum);
      float midMask       = 1.0 - shadowMask - highlightMask;
      midMask = clamp(midMask, 0.0, 1.0);
      float contMult = shadowMask * shadowC + highlightMask * highlightC + midMask * midC;
      lum = (lum - 0.5) * contMult + 0.5;
      return clamp(lum, 0.0, 1.0);
    }

    float3 applyDesat(float3 col, float lum, float shadowD, float midD, float highlightD){
      float shadowMask    = smoothstep(0.4, 0.0, lum);
      float highlightMask = smoothstep(0.6, 1.0, lum);
      float midMask       = clamp(1.0 - shadowMask - highlightMask, 0.0, 1.0);
      float desatAmt = shadowMask * shadowD + midMask * midD + highlightMask * highlightD;
      return mix(col, float3(lum), desatAmt);
    }

    float filmGrain(float2 uv, float amzLocal_time, float speed, float amzLocal_size){
      float t = floor(amzLocal_time * speed);
      float2 scaledUV = uv * (500.0 / max(amzLocal_size, 0.1));
      float n = hash21(scaledUV + float2(t * 1.7, t * 3.1));
      float n2 = hash21(scaledUV * 1.3 + float2(t * 2.3, t * 1.5));
      return (n + n2) * 0.5;
    }

    float3 applyHalation(float3 col, float lum, float strength, float threshold, float3 hColor){
      float halMask = smoothstep(threshold - 0.1, threshold + 0.1, lum);
      float3 halGlow = hColor * halMask * strength;
      return clamp(col + halGlow, 0.0, 1.0);
    }

    float3 applyTint(float3 col, float lum, float3 sTint, float sStr, float3 hTint, float hStr){
      float shadowMask    = smoothstep(0.4, 0.0, lum);
      float highlightMask = smoothstep(0.6, 1.0, lum);
      col = mix(col, col * sTint * 2.0, shadowMask * sStr);
      col = mix(col, col * hTint * 2.0, highlightMask * hStr);
      return clamp(col, 0.0, 1.0);
    }

    void amzRender(){

      float2 uv = amzScreenNorm();
      float t = time;

      float4 src = amzTexture(0, uv);
      float3 col = src.rgb;

      float lum = luminance(srgbToLinear(col));

      float lumContrast = filmContrast(
        lum,
        amzp_shadowContrast, amzp_highlightContrast, amzp_midContrast,
        amzp_blackPoint, amzp_whitePoint
      );

      lumContrast = toneCurve(lumContrast, amzp_liftShadows, amzp_gainHighlights, amzp_gamma);

      float3 bwHigh = float3(lumContrast);

      float3 colDesat = applyDesat(col, lum, amzp_shadowDesat, amzp_midDesat, amzp_highlightDesat);

      float3 blended;
      float bmf = float(int(amzp_blendMode));
      if(bmf < 1.5){
        blended = blendOverlay(colDesat, bwHigh);
      } else if(bmf < 2.5){
        blended = blendSoftLight(colDesat, bwHigh);
      } else {
        blended = blendHardLight(colDesat, bwHigh);
      }

      float3 result = mix(colDesat, blended, amzp_bypassStrength);

      float lumResult = luminance(srgbToLinear(result));

      if((amzp_halationEnable>0.5)){
        result = applyHalation(result, lumResult, amzp_halationStrength, amzp_halationThreshold, amzp_halationColor.rgb);
      }

      result = applyTint(result, lumResult, amzp_shadowTint.rgb, amzp_shadowTintStr, amzp_highlightTint.rgb, amzp_highlightTintStr);

      if((amzp_grainEnable>0.5)){
        float grain = filmGrain(uv, t, amzp_grainSpeed, amzp_grainSize);
        float grainMask = 1.0 - abs(lumResult - 0.5) * 0.5;
        result += (grain - 0.5) * amzp_grainStrength * grainMask;
        result = clamp(result, 0.0, 1.0);
      }

      result = mix(col, result, amzp_overallStrength);

      if((amzp_bwPreview>0.5)){
        float bwLum = filmContrast(
          luminance(srgbToLinear(col)),
          amzp_shadowContrast, amzp_highlightContrast, amzp_midContrast,
          amzp_blackPoint, amzp_whitePoint
        );
        bwLum = toneCurve(bwLum, amzp_liftShadows, amzp_gainHighlights, amzp_gamma);
        amzOutput = float4(float3(bwLum), src.a);
        return;
      }

      amzOutput = float4(result, src.a);
    }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

